//! The Library focus in a window of its own (Window › Library,
//! `library.window`): it opens in an OS window of its own and comes to
//! the front when asked again; it shows the main window's Library in a
//! gallery of its own (its own search, filter and selection), the one
//! commands act on while it has the input, and a mark made there is the
//! main window's too; open at the last quit, it opens again at the
//! next start. The snapshot (`tests/snapshots/library-window-*.png`) is
//! regenerated by the box's `gui-snapshots` job with `test=library_window`.

use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

use egui::{ViewportId, vec2};
use egui_kittest::Harness;
use egui_kittest::kittest::{NodeT as _, Queryable as _};
use egui_pop::api::windows::WindowId;
use helios_gui::library::{Entry, WINDOW_GALLERY};
use helios_gui::shell::{LIBRARY_WINDOW, LIBRARY_WINDOW_COMMAND};
use helios_gui::{Shell, headless, helios_panels};
use helios_shell::commands::Origin;
use serde_json::{Value, json};

use crate::shot::Shots as _;

fn scratch(name: &str) -> PathBuf {
    static NEXT: AtomicU64 = AtomicU64::new(0);
    let dir = std::env::temp_dir().join(format!(
        "helios-gui-library-window-{name}-{}-{}",
        std::process::id(),
        NEXT.fetch_add(1, Ordering::Relaxed)
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

/// Photos a, b and c.
fn entries() -> Vec<Entry> {
    ["a", "b", "c"]
        .iter()
        .map(|id| Entry {
            id: (*id).to_string(),
            name: format!("{id}.jpg"),
            ..Entry::default()
        })
        .collect()
}

fn run(h: &mut Harness<'_, Shell>, command: &str, args: Value) {
    h.state_mut().run(command, args, Origin::User).unwrap();
    h.run_steps(3);
}

/// The windows the main window's last pass declared, as eframe would
/// open them.
fn declared(h: &Harness<'static, Shell>) -> Vec<ViewportId> {
    h.output()
        .viewport_output
        .iter()
        .filter(|(v, o)| **v != ViewportId::ROOT && o.viewport_ui_cb.is_some())
        .map(|(v, _)| *v)
        .collect()
}

#[test]
fn window_library_opens_the_focus_in_its_own_window_and_again_brings_it_forward() {
    let mut h = headless::harness(Shell::new(helios_panels(), None), vec2(1280.0, 800.0));
    h.ctx.set_embed_viewports(false);
    h.state_mut().draw_frame(true);
    h.run();
    assert!(declared(&h).is_empty(), "no window but the main one");
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    let windows = declared(&h);
    assert_eq!(windows.len(), 1, "the focus's own window: {windows:?}");
    let app = h.state().app().handle().clone();
    assert_eq!(
        app.window_viewport(&WindowId::new(LIBRARY_WINDOW)),
        Some(windows[0])
    );
    // Asked again: the same window, not a second one.
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    assert_eq!(declared(&h), windows);
    // Closed: the focus closes, the main window stays.
    app.close_window(&WindowId::new(LIBRARY_WINDOW));
    h.run_steps(3);
    assert!(declared(&h).is_empty());
    assert_eq!(h.state().library_window_state()["open"], false);
}

/// The cell labelled `name` in the Library window: the main window's
/// filmstrip draws one too, under the window and partly within its
/// area, so the cell is looked for among the window's own nodes.
fn in_window<'a>(h: &'a Harness<'_, Shell>, name: &'a str) -> egui_kittest::Node<'a> {
    h.get_by_role_and_label(egui::accesskit::Role::Window, "Library")
        .get_by_label(name)
}

/// A pointer press and release on `at`, each on frames of its own, as a
/// hand clicks: the grid's cells also sense drags.
fn click_at(h: &mut Harness<'_, Shell>, at: egui::Pos2) {
    h.event(egui::Event::PointerMoved(at));
    h.run_steps(1);
    for pressed in [true, false] {
        h.event(egui::Event::PointerButton {
            pos: at,
            button: egui::PointerButton::Primary,
            pressed,
            modifiers: egui::Modifiers::NONE,
        });
        h.run_steps(2);
    }
}

#[test]
fn the_library_window_s_selection_is_the_one_commands_act_on() {
    let mut shell = Shell::new(helios_panels(), None);
    shell.set_library(entries());
    let mut h = headless::harness(shell, vec2(1600.0, 1000.0));
    h.run();
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    assert_eq!(h.state().library_window_state()["open"], true);
    // A click on b in the window's grid: the window's gallery is the one
    // in force.
    let at = in_window(&h, "b.jpg").rect().center();
    click_at(&mut h, at);
    assert_eq!(h.state().library().selected(), Some(1));
    // A command, from wherever it comes, acts on that selection.
    run(&mut h, "vault.rate", json!({ "stars": 4 }));
    let library = h.state().library();
    assert_eq!(library.entries[1].rating, 4);
    assert_eq!(library.entries[0].rating, 0, "only the selection");
}

#[test]
fn auto_advance_ticked_in_the_library_window_is_that_window_s_only() {
    let mut shell = Shell::new(helios_panels(), None);
    shell.set_library(entries());
    let mut h = headless::harness(shell, vec2(1600.0, 1000.0));
    h.run();
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    // The toggle in the window's Results bar, by its name (accesskit).
    let toggle = h
        .get_by_role_and_label(egui::accesskit::Role::Window, "Library")
        .get_by_label_contains("Auto-advance");
    assert_eq!(
        toggle.accesskit_node().toggled(),
        Some(egui::accesskit::Toggled::False)
    );
    let at = toggle.rect().center();
    click_at(&mut h, at);
    h.run_steps(3);
    let mut lib = h.state().library_mut();
    assert!(
        lib.with_gallery(WINDOW_GALLERY, |l| l.auto_advance()),
        "on in the window"
    );
    assert!(
        !lib.with_gallery(helios_gui::library::MAIN_GALLERY, |l| l.auto_advance()),
        "the main window's Results keep theirs"
    );
}

#[test]
fn a_click_on_a_cell_of_the_library_window_selects_it() {
    let mut shell = Shell::new(helios_panels(), None);
    shell.set_library(entries());
    let mut h = headless::harness(shell, vec2(1600.0, 1000.0));
    h.run();
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    // Through accesskit, as agents and screen readers click.
    in_window(&h, "a.jpg").click_accesskit();
    h.run_steps(2);
    assert_eq!(h.state().library().selected(), Some(0), "a, clicked");
    // With the pointer, the cell under it; the main window's filmstrip,
    // drawn under the window, does not take the click.
    let at = in_window(&h, "c.jpg").rect().center();
    click_at(&mut h, at);
    assert_eq!(h.state().library().selected(), Some(2), "c, clicked");
}

/// The host's part of the Metadata section: each photo's capture details
/// as asked, a camera named after the photo, over a few frames.
fn feed_exif(h: &mut Harness<'_, Shell>) {
    for _ in 0..8 {
        loop {
            let wanted = h.state_mut().library_mut().take_exif_wanted();
            let Some(id) = wanted else { break };
            let mut fields = serde_json::Map::new();
            fields.insert("camera_model".into(), json!(format!("Cam-{id}")));
            h.state_mut().library_mut().set_exif(id, fields);
        }
        h.run_steps(1);
    }
}

/// Each Library view's Metadata section shows the photo under its own
/// cursor: a in the main panel, b in the Library window. Once, the cursor
/// was one for both views: the photo selected last, in either view, was
/// the one both sections showed.
#[test]
fn each_view_s_metadata_shows_the_photo_under_its_own_cursor() {
    use egui::accesskit::Role;
    let mut shell = Shell::new(helios_panels(), None);
    shell.set_library(entries());
    shell.library_mut().select(0);
    shell
        .library_mut()
        .with_gallery(WINDOW_GALLERY, |lib| lib.select(1));
    let mut h = headless::harness(shell, vec2(1600.0, 1000.0));
    h.run_steps(4);
    feed_exif(&mut h);
    // The main panel: a, though b was selected last, in the window.
    assert_eq!(
        h.query_all_by_label("Cam-a").count(),
        1,
        "the main panel shows a"
    );
    assert_eq!(
        h.query_all_by_label("Cam-b").count(),
        0,
        "the window's b, in the main panel"
    );
    // The Library window: b.
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    feed_exif(&mut h);
    let window = h.get_by_role_and_label(Role::Window, "Library");
    window.get_by_label("Cam-b");
    assert!(
        window.query_by_label("Cam-a").is_none(),
        "the window's section shows a, the main panel's photo"
    );
}

#[test]
fn the_library_window_open_at_the_last_quit_opens_again_at_the_start() {
    let dir = scratch("restore");
    {
        let shell = Shell::build(helios_panels(), None, Some(dir.clone()));
        let mut h = headless::harness(shell, vec2(1280.0, 800.0));
        h.run();
        run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
        h.state().app().handle().flush_documents();
    }
    let shell = Shell::build(helios_panels(), None, Some(dir.clone()));
    assert_eq!(shell.library_window_state()["open"], true, "opened again");
    let mut h = headless::harness(shell, vec2(1280.0, 800.0));
    h.run();
    // Closed, it stays closed at the next start.
    h.state_mut().close_library_window();
    h.run_steps(3);
    h.state().app().handle().flush_documents();
    drop(h);
    let shell = Shell::build(helios_panels(), None, Some(dir.clone()));
    assert_eq!(shell.library_window_state()["open"], false);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn library_window_snapshots() {
    let mut results = egui_kittest::SnapshotResults::new();
    let mut shell = Shell::new(helios_panels(), None);
    shell.set_library(entries());
    // The window's own selection.
    shell
        .library_mut()
        .with_gallery(WINDOW_GALLERY, |lib| lib.select(1));
    let mut h = headless::harness(shell, vec2(1280.0, 800.0));
    h.run();
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    h.run_steps(4);
    results.add(h.try_window_shot("library-window-pop-dark-1x", "Library"));
}

/// The Metadata section on one photo, then on two whose fields differ
/// (‹mixed›), in the Library window.
#[test]
fn library_metadata_snapshots() {
    let mut results = egui_kittest::SnapshotResults::new();
    let mut shell = Shell::new(helios_panels(), None);
    let mut list = entries();
    for (e, title) in list.iter_mut().zip(["Harbour", "Market", "Dunes"]) {
        e.title = Some(title.to_string());
        e.creator = Some("Ann Lee".into());
        e.rating = 3;
        e.labels = vec!["green".into()];
        e.tags = vec!["Trips|2026".into()];
    }
    list[1].rating = 5;
    list[1].tags.push("Market".into());
    shell.set_library(list);
    shell
        .library_mut()
        .with_gallery(WINDOW_GALLERY, |lib| lib.select(0));
    let mut h = headless::harness(shell, vec2(1280.0, 800.0));
    h.run();
    run(&mut h, LIBRARY_WINDOW_COMMAND, Value::Null);
    h.run_steps(4);
    results.add(h.try_window_shot("library-metadata-single", "Library"));
    h.state_mut()
        .library_mut()
        .with_gallery(WINDOW_GALLERY, |lib| {
            lib.select_ids(&["a".to_string(), "b".to_string()]);
        });
    h.run_steps(4);
    h.get_by_label("2 photos selected");
    results.add(h.try_window_shot("library-metadata-mixed", "Library"));
}

/// The Metadata section in the main window's narrow Library panel: every
/// control (stars, each colour label, pick and reject, the text fields)
/// lies inside the panel, none under the viewport beside it.
#[test]
fn the_metadata_section_fits_the_narrow_library_panel() {
    use egui::accesskit::Role;
    let mut shell = Shell::new(helios_panels(), None);
    shell.set_library(entries());
    shell.library_mut().select(0);
    let mut h = headless::harness(shell, vec2(1600.0, 1000.0));
    h.run_steps(4);
    let panel = h.state().target_rect("helios.filters").unwrap();
    assert!(panel.width() < 400.0, "the narrow Filters panel: {panel:?}");
    let inside = |what: &str, r: egui::Rect| {
        assert!(
            r.min.x >= panel.min.x - 0.5 && r.max.x <= panel.max.x + 0.5,
            "{what} at {r:?} runs past the Filters panel {panel:?}"
        );
    };
    let marks: Vec<(String, egui::Rect)> = h
        .query_all_by_role(Role::CheckBox)
        .map(|n| (format!("{n:?}"), n.rect()))
        .collect();
    assert!(marks.len() >= 7, "5 labels and 2 flags: {marks:?}");
    for (name, r) in &marks {
        inside(name, *r);
    }
    for label in ["Title", "Description", "Creator", "Copyright", "Rating"] {
        let found: Vec<egui::Rect> = h.query_all_by_label(label).map(|n| n.rect()).collect();
        assert!(!found.is_empty(), "no {label}");
        for r in found {
            inside(label, r);
        }
    }
}
